SELECT XR2.JEITO TIPO, COUNT(DISTINCT XR2.VIDEO_ID) QTD FROM PRATICAS XR2 JOIN VIDEOS V ON V.ID = XR2.VIDEO_ID WHERE XR2.CONSELHO = 0 AND V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') GROUP BY XR2.JEITO ORDER BY QTD DESC, XR2.JEITO